(() => {
  function getRank(cardId, cards) {
    if (cards && cards[cardId] && cards[cardId].rank) return cards[cardId].rank;
    const m = cardId.match(/^(10|[2-9AJQK])[SHDC]$/);
    if (m) return m[1];
    return null;
  }

  function eliminatePairs(hand, cards) {
    const remaining = [];
    const discarded = [];
    const keptRank = new Map();
    for (const card of hand) {
      const r = getRank(card, cards);
      if (r === null) { remaining.push(card); continue; }
      if (keptRank.has(r)) {
        const kept = keptRank.get(r);
        keptRank.delete(r);
        const idx = remaining.indexOf(kept);
        if (idx !== -1) remaining.splice(idx, 1);
        discarded.push(kept, card);
      } else {
        keptRank.set(r, card);
        remaining.push(card);
      }
    }
    return { hand: remaining, discarded };
  }

  function shuffleArray(arr, seed) {
    let s = seed;
    for (let i = arr.length - 1; i > 0; i--) {
      s = (s * 1103515245 + 12345) % 2147483648;
      const j = s % (i + 1);
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
    return { arr, seed: s };
  }

  function parseActionId(id) {
    const m = /^draw_(\d+)_(\d+)$/.exec(id);
    if (m) return { target: parseInt(m[1], 10), index: parseInt(m[2], 10) };
    throw new Error('bad action id ' + id);
  }

  function setup(deck, playerCount, cards) {
    const hands = [[], []];
    for (let i = 0; i < deck.length; i++) hands[i % 2].push(deck[i]);
    let discard = [];
    for (let p = 0; p < 2; p++) {
      const { hand, discarded } = eliminatePairs(hands[p], cards);
      hands[p] = hand;
      discard = discard.concat(discarded);
    }
    let finished = false, winners = [], scores = [0,0];
    if (hands[0].length === 0 || hands[1].length === 0) {
      finished = true;
      winners = hands[0].length === 0 ? [0] : [1];
      scores[winners[0]] = 1;
    }
    return {
      hands,
      deck: [],
      discard,
      current_player: 0,
      finished,
      winners,
      scores,
      phase: 'playing',
      data: { seed: 12345, initialDeal: true }
    };
  }

  function actions(state, cards) {
    if (state.finished) return [];
    const current = state.current_player;
    const opponent = 1 - current;
    const oppHand = state.hands[opponent];
    const acts = [];
    for (let i = 0; i < oppHand.length; i++) {
      acts.push({
        id: `draw_${opponent}_${i}`,
        label: `从玩家${opponent+1}手牌位置${i+1}抽牌`,
        target_player: opponent,
        card_index: i
      });
    }
    return acts;
  }

  function step(state, action, cards) {
    if (state.finished) return state;
    const hands = state.hands.map(arr => arr.slice());
    let discard = state.discard.slice();
    const current = state.current_player;
    const { target, index } = parseActionId(action.id);
    if (target === current) return state;
    const oppHand = hands[target];
    if (index < 0 || index >= oppHand.length) return state;
    const card = oppHand[index];
    oppHand.splice(index, 1);
    hands[current].push(card);

    const { hand: newCurr, discarded: disc } = eliminatePairs(hands[current], cards);
    hands[current] = newCurr;
    discard = discard.concat(disc);

    let seed = state.data && state.data.seed !== undefined ? state.data.seed : 12345;
    if (oppHand.length > 1) {
      const result = shuffleArray(oppHand, seed);
      hands[target] = result.arr;
      seed = result.seed;
    }

    let finished = false, winners = [], scores = state.scores.slice();
    if (hands[0].length === 0 || hands[1].length === 0) {
      finished = true;
      winners = hands[0].length === 0 ? [0] : [1];
      scores = [0,0];
      scores[winners[0]] = 1;
    }

    const nextPlayer = finished ? current : (1 - current);
    return {
      hands,
      deck: state.deck.slice(),
      discard,
      current_player: nextPlayer,
      finished,
      winners,
      scores,
      phase: finished ? 'finished' : 'playing',
      data: { ...state.data, seed }
    };
  }

  return { setup, actions, step };
})()
